import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.Mockito;
import org.mockito.junit.MockitoJUnitRunner;

import java.util.Collections;
import java.util.List;
import java.util.Map;

@RunWith(MockitoJUnitRunner.class)
public class CommentsConfigurationTest {

    @Mock
    private Map<String, List<String>> commentsMap;

    private CommentsConfiguration commentsConfiguration;

    @Test
    public void newCommentsConfiguration_EmptyComments() {
        commentsConfiguration = new CommentsConfiguration();
        assertIsEmpty(commentsConfiguration.comments);
    }

    @Test
    public void newCommentsConfiguration_SingleEntry() {
        Map<String, List<String>> commentMap = createCommentMap("testPath", Collections.singletonList("comment"));
        commentsConfiguration = new CommentsConfiguration(commentMap);
        assertEquals(1, commentsConfiguration.comments.size());
        assertEquals(1, commentsConfiguration.comments.get("testPath").size());
    }

    @Test
    public void setComment_OneEntry() {
        Map<String, List<String>> commentMap = createCommentMap();
        commentsConfiguration = new CommentsConfiguration(commentMap);
        String[] commentLines = {"comment1", "comment2"};
        commentsConfiguration.setComment("testPath", commentLines);
        assertEquals(1, commentsConfiguration.comments.size());
        assertEquals(2, commentsConfiguration.comments.get("testPath").size());
    }

    @Test
    public void setComment_MultipleEntries() {
        Map<String, List<String>> commentMap = createCommentMap();
        commentsConfiguration = new CommentsConfiguration(commentMap);
        String[] commentLines1 = {"comment1", "comment2"};
        String[] commentLines2 = {"comment3", "comment4"};
        commentsConfiguration.setComment("testPath1", commentLines1);
        commentsConfiguration.setComment("testPath2", commentLines2);
        assertEquals(2, commentsConfiguration.comments.size());
        assertEquals(2, commentsConfiguration.comments.get("testPath1").size());
        assertEquals(2, commentsConfiguration.comments.get("testPath2").size());
    }

    @Test
    public void getAllComments_EmptyMap() {
        Map<String, List<String>> commentMap = Collections.emptyMap();
        CommentsConfiguration commentsConfig = new CommentsConfiguration(commentMap);
        assertIsEmpty(commentsConfig.getAllComments());
    }

    @Test
    public void getAllComments_SingleEntry() {
        Map<String, List<String>> commentMap = createCommentMap("testPath", Collections.singletonList("comment"));
        CommentsConfiguration commentsConfig = new CommentsConfiguration(commentMap);
        Map<String, List<String>> allComments = commentsConfig.getAllComments();
        assertEquals(1, allComments.size());
    }

    @Test
    public void getAllComments_MultipleEntries() {
        Map<String, List<String>> commentMap = createCommentMap("testPath1", Collections.singletonList("comment1"), "testPath2", Collections.singletonList("comment2"));
        CommentsConfiguration commentsConfig = new CommentsConfiguration(commentMap);
        Map<String, List<String>> allComments = commentsConfig.getAllComments();
        assertEquals(2, allComments.size());
    }

    private void assertIsEmpty(Map<String, List<String>> map) {
        assertEquals(0, map.size());
        for (List<String> list : map.values()) {
            assertEquals(0, list.size());
        }
    }

    private Map<String, List<String>> createCommentMap(String... paths) {
        Map<String, List<String>> commentMap = new HashMap<>();
        for (String path : paths) {
            commentMap.put(path, Collections.singletonList("comment"));
        }
        return commentMap;
    }
}
